param([ValidateSet('Preflight','Install','Inspect')][string]$Phase)
$ErrorActionPreference='Stop';$inputData=[Console]::In.ReadToEnd()|ConvertFrom-Json;$taskRoot=Split-Path $PSScriptRoot -Parent;$root='C:\ProgramData\CormierDnsManager\RecoveryChannel';$taskName='Cormier DNS Manager Recovery Agent';$session=New-PSSession -ComputerName domain02.cormierconsulting.com
try{
 if($Phase -eq 'Preflight'){
  Invoke-Command -Session $session -ArgumentList $root,$taskName -ScriptBlock {param($root,$taskName);$ErrorActionPreference='Stop';$bridgeRoot='C:\ProgramData\CormierDnsManager';$installed=Get-Content -LiteralPath (Join-Path $bridgeRoot 'configuration.json') -Raw|ConvertFrom-Json;$acl=Get-Acl -LiteralPath $bridgeRoot;if(!$acl.AreAccessRulesProtected -or @($acl.Access|Where-Object {$_.AccessControlType -eq 'Allow' -and $_.IdentityReference.Translate([Security.Principal.SecurityIdentifier]).Value -notin @('S-1-5-18','S-1-5-32-544')}).Count){throw 'Installed bridge root is not private'};if([IO.Path]::GetFullPath($installed.kubeconfig) -cne (Join-Path $bridgeRoot 'kubeconfig.json')){throw 'Installed bridge credential path differs'};if(Test-Path -LiteralPath (Join-Path $bridgeRoot 'credential-recovery-active.json')){throw 'An installed credential recovery is incomplete'};if(Test-Path -LiteralPath $root){throw 'Production recovery directory already exists'};if(Get-ScheduledTask -TaskName $taskName -ErrorAction SilentlyContinue){throw 'Production recovery task already exists'};@{rootAbsent=$true;taskAbsent=$true;configurationHash=(Get-FileHash -LiteralPath (Join-Path $bridgeRoot 'configuration.json')).Hash;credentialHash=(Get-FileHash -LiteralPath $installed.kubeconfig).Hash;bridgeHash=(Get-FileHash -LiteralPath (Join-Path $bridgeRoot 'windows-dns-bridge.ps1')).Hash;bridgeState=[string](Get-ScheduledTask -TaskName 'Cormier DNS Manager Bridge').State}|ConvertTo-Json}
 }elseif($Phase -eq 'Install'){
  if($inputData.id -cnotmatch '^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'){throw 'Invalid bootstrap identity'}
  Invoke-Command -Session $session -ArgumentList $root,$taskName,$inputData.id -ScriptBlock {param($root,$taskName,$id);$ErrorActionPreference='Stop';if((Test-Path -LiteralPath $root) -or (Get-ScheduledTask -TaskName $taskName -ErrorAction SilentlyContinue)){throw 'Existing recovery installation prevents bootstrap'};New-Item -ItemType Directory -Path $root|Out-Null;& icacls $root /inheritance:r /grant:r '*S-1-5-18:(OI)(CI)F' '*S-1-5-32-544:(OI)(CI)F'|Out-Null;if($LASTEXITCODE -ne 0){throw 'Recovery directory privacy failed'};[IO.File]::WriteAllText((Join-Path $root 'bootstrap-owner.json'),(@{id=$id}|ConvertTo-Json -Compress))}
  $hashes=@{};foreach($name in @('windows-dns-credential-recovery.ps1','windows-recovery-envelope.ps1','windows-recovery-channel.ps1','windows-recovery-agent-api.ps1','windows-recovery-agent.ps1')){$source=Join-Path $taskRoot ('live-management/'+$name);Copy-Item -LiteralPath $source -Destination (Join-Path $root $name) -ToSession $session;$hashes[$name]=(Get-FileHash -LiteralPath $source).Hash}
  Invoke-Command -Session $session -ArgumentList $root,$taskName,$inputData,$hashes -ScriptBlock {
   param($root,$taskName,$inputData,$hashes);$ErrorActionPreference='Stop';foreach($name in $hashes.Keys){if((Get-FileHash -LiteralPath (Join-Path $root $name)).Hash -cne $hashes[$name]){throw 'Transferred bootstrap source differs'}};foreach($name in @('windows-dns-credential-recovery.ps1','windows-recovery-envelope.ps1','windows-recovery-channel.ps1','windows-recovery-agent-api.ps1')){. (Join-Path $root $name)}
   $bridgeRoot='C:\ProgramData\CormierDnsManager';$installed=Get-Content -LiteralPath (Join-Path $bridgeRoot 'configuration.json') -Raw|ConvertFrom-Json;if((Get-FileHash -LiteralPath $installed.kubeconfig).Hash -cne $inputData.before.credentialHash -or (Get-FileHash -LiteralPath (Join-Path $bridgeRoot 'configuration.json')).Hash -cne $inputData.before.configurationHash -or (Get-FileHash -LiteralPath (Join-Path $bridgeRoot 'windows-dns-bridge.ps1')).Hash -cne $inputData.before.bridgeHash){throw 'Reviewed installed bridge baseline changed'}
   $settings=[pscustomobject]@{version=1;namespace='dns-system';clusterUid=$inputData.clusterUid;accountUid=$inputData.accountUid;agentAccountUid=$inputData.agentAccountUid;requestUid=$inputData.requestUid;receiptUid=$inputData.receiptUid;channelRoot=$root;bridgeRoot=$bridgeRoot;kubectl=$installed.kubectl;clusterCaData=$inputData.clusterCaData;bridgeSourceDigest=$inputData.before.bridgeHash.ToLowerInvariant()}
   $config=@{apiVersion='v1';kind='Config';clusters=@(@{name='cluster';cluster=@{server='https://10.99.15.50:6443';'tls-server-name'='kubernetes.cormierconsulting.io';'certificate-authority-data'=$settings.clusterCaData}});users=@(@{name='bridge';user=@{token=$inputData.agentToken}});contexts=@(@{name='bridge';context=@{cluster='cluster';user='bridge';namespace='dns-system'}});'current-context'='bridge'}
   Write-DnsRecoveryFile (Join-Path $root 'agent.json') ([Text.Encoding]::UTF8.GetBytes(($settings|ConvertTo-Json -Depth 8 -Compress)));Write-DnsRecoveryFile (Join-Path $root 'recovery-kubeconfig.json') ([Text.Encoding]::UTF8.GetBytes(($config|ConvertTo-Json -Depth 12 -Compress)));$settings=Assert-DnsRecoveryAgentSettings $settings
   if(!(Confirm-DnsRecoveryIdentity $settings (Join-Path $root 'recovery-kubeconfig.json') 'dns-windows-recovery-agent' $settings.agentAccountUid)){throw 'New independent identity was not authenticated'};$queue=Invoke-DnsRecoveryKube $settings (Join-Path $root 'recovery-kubeconfig.json') secret 'dns-windows-recovery-request';if($queue.metadata.uid -cne $settings.requestUid -or $queue.data.'request.jwe'){throw 'Bootstrap requires the pinned empty queue'}
   $key=New-DnsRecoveryChannelKey $root;$null=Invoke-DnsRecoveryAgentIteration $settings
   $action=New-ScheduledTaskAction -Execute 'powershell.exe' -Argument ('-NoProfile -NonInteractive -File "'+(Join-Path $root 'windows-recovery-agent.ps1')+'" -Continuous');$startup=New-ScheduledTaskTrigger -AtStartup;$repeat=New-ScheduledTaskTrigger -Once -At (Get-Date).AddMinutes(1) -RepetitionInterval ([TimeSpan]::FromMinutes(1));$options=New-ScheduledTaskSettingsSet -MultipleInstances IgnoreNew -ExecutionTimeLimit ([TimeSpan]::Zero) -StartWhenAvailable;$principal=New-ScheduledTaskPrincipal -UserId 'SYSTEM' -LogonType ServiceAccount -RunLevel Highest;$null=Register-ScheduledTask -TaskName $taskName -Action $action -Trigger @($startup,$repeat) -Settings $options -Principal $principal;Start-ScheduledTask -TaskName $taskName
   $started=[DateTime]::UtcNow;$health=$null;for($i=0;$i -lt 45;$i++){if(Test-Path -LiteralPath (Join-Path $root 'last-agent-health.json')){$health=Get-Content -LiteralPath (Join-Path $root 'last-agent-health.json') -Raw|ConvertFrom-Json;if($health.reachable -and [DateTime]::Parse($health.at).ToUniversalTime() -ge $started){break}};Start-Sleep -Seconds 1};if(!$health -or !$health.reachable -or (Get-ScheduledTask -TaskName $taskName).State -ne 'Running'){throw 'Independent production heartbeat was not confirmed'}
   if((Get-FileHash -LiteralPath $installed.kubeconfig).Hash -cne $inputData.before.credentialHash -or (Get-FileHash -LiteralPath (Join-Path $bridgeRoot 'configuration.json')).Hash -cne $inputData.before.configurationHash -or (Get-ScheduledTask -TaskName 'Cormier DNS Manager Bridge').State -ne 'Running'){throw 'Installed ordinary bridge was not preserved'}
   @{passed=$true;key=$key;sourceHashes=$hashes;root=$root;taskName=$taskName;agentAccountUid=$settings.agentAccountUid;health=$health;credentialPreserved=$true;configurationPreserved=$true;ordinaryBridgeRunning=$true;multipleInstances=[string](Get-ScheduledTask -TaskName $taskName).Settings.MultipleInstances}|ConvertTo-Json -Depth 10
  }
 }else{
