   param($root,$taskName,$id);$ErrorActionPreference='Stop';if(!(Test-Path -LiteralPath $root)){@{rootAbsent=$true}|ConvertTo-Json;return};foreach($name in @('windows-dns-credential-recovery.ps1','windows-recovery-envelope.ps1','windows-recovery-channel.ps1','windows-recovery-agent-api.ps1')){. (Join-Path $root $name)}
   $owner=Get-Content -LiteralPath (Join-Path $root 'bootstrap-owner.json') -Raw|ConvertFrom-Json;if($owner.id -cne $id){throw 'Existing production bootstrap belongs to another installation'};$settings=Get-Content -LiteralPath (Join-Path $root 'agent.json') -Raw|ConvertFrom-Json;$settings=Assert-DnsRecoveryAgentSettings $settings;$rsa=Get-DnsRecoveryChannelKey $root;try{$key=Get-DnsChannelPublicKey $rsa}finally{$rsa.Dispose()};$health=Get-Content -LiteralPath (Join-Path $root 'last-agent-health.json') -Raw|ConvertFrom-Json
   $hashes=@{};foreach($name in @('windows-dns-credential-recovery.ps1','windows-recovery-envelope.ps1','windows-recovery-channel.ps1','windows-recovery-agent-api.ps1','windows-recovery-agent.ps1')){$hashes[$name]=(Get-FileHash -LiteralPath (Join-Path $root $name)).Hash}
   $exclusive=$false;try{$probe=Open-DnsRecoveryLock $root 'recovery-poller.lock';$probe.Dispose()}catch{if($_.Exception.Message -cne 'Another DNS operation holds the recovery lock'){throw};$exclusive=$true}
   @{rootPresent=$true;key=$key;health=$health;taskState=[string](Get-ScheduledTask -TaskName $taskName).State;sourceHashes=$hashes;agentAccountUid=$settings.agentAccountUid;requestUid=$settings.requestUid;receiptUid=$settings.receiptUid;exclusivePollerLockHeld=$exclusive;leasePresent=(Test-Path -LiteralPath (Join-Path $settings.bridgeRoot 'credential-recovery-active.json'));credentialHash=(Get-FileHash -LiteralPath (Join-Path $settings.bridgeRoot 'kubeconfig.json')).Hash;configurationHash=(Get-FileHash -LiteralPath (Join-Path $settings.bridgeRoot 'configuration.json')).Hash}|ConvertTo-Json -Depth 8
  }
 }
}finally{Remove-PSSession $session}
